import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Why SMQL?","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/why-smql.md","filePath":"introduction/why-smql.md"}'),s={name:"introduction/why-smql.md"};function r(n,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="why-smql" tabindex="-1">Why SMQL? <a class="header-anchor" href="#why-smql" aria-label="Permalink to &quot;Why SMQL?&quot;">​</a></h1><p>SMQL is the right choice when your entities have well-defined lifecycles. Here are common patterns where it excels.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="customer-support-tickets" tabindex="-1">Customer Support Tickets <a class="header-anchor" href="#customer-support-tickets" aria-label="Permalink to &quot;Customer Support Tickets&quot;">​</a></h3><p>Tickets flow through <code>open → triaged → in_progress → resolved → closed</code> with guard rules (only assignee can resolve), timeouts (auto-close after 7 days), and audit trails (who escalated and when).</p><h3 id="order-processing" tabindex="-1">Order Processing <a class="header-anchor" href="#order-processing" aria-label="Permalink to &quot;Order Processing&quot;">​</a></h3><p>Orders involve parent-child composition: an <code>Order</code> contains <code>LineItem</code> children and an optional <code>Shipment</code>. Guards like <code>ALL(items, STATE IS confirmed)</code> ensure all items are ready before fulfillment.</p><h3 id="ci-cd-pipelines" tabindex="-1">CI/CD Pipelines <a class="header-anchor" href="#ci-cd-pipelines" aria-label="Permalink to &quot;CI/CD Pipelines&quot;">​</a></h3><p>Three-level composition: <code>Pipeline → Stage → Job</code>. A pipeline passes when all stages pass; a stage fails when any job fails. SMQL&#39;s <code>ALL()</code> and <code>ANY()</code> predicates express this naturally.</p><h3 id="approval-workflows" tabindex="-1">Approval Workflows <a class="header-anchor" href="#approval-workflows" aria-label="Permalink to &quot;Approval Workflows&quot;">​</a></h3><p>Documents move through <code>draft → submitted → under_review → approved/rejected</code>. Guards enforce role-based rules (<code>ACTOR.role == &quot;reviewer&quot;</code>), and timeouts escalate stale reviews.</p><h3 id="billing-subscriptions" tabindex="-1">Billing &amp; Subscriptions <a class="header-anchor" href="#billing-subscriptions" aria-label="Permalink to &quot;Billing &amp; Subscriptions&quot;">​</a></h3><p>Subscriptions cycle through <code>trial → active → past_due → cancelled → expired</code>. Timeouts handle grace periods. Data constraints ensure payment methods are set before activation.</p><h3 id="iot-device-management" tabindex="-1">IoT Device Management <a class="header-anchor" href="#iot-device-management" aria-label="Permalink to &quot;IoT Device Management&quot;">​</a></h3><p>Devices transition through <code>provisioned → online → degraded → offline → decommissioned</code>. Sensor data is stored as instance data, and transition trails provide a complete operational history.</p><h2 id="why-not-just-sql" tabindex="-1">Why Not Just SQL? <a class="header-anchor" href="#why-not-just-sql" aria-label="Permalink to &quot;Why Not Just SQL?&quot;">​</a></h2><p>You <em>can</em> model state machines in SQL. Many teams do. But you&#39;ll end up building:</p><ol><li><strong>A transition validation layer</strong> — checking which states can reach which</li><li><strong>A guard evaluation system</strong> — checking preconditions before transitions</li><li><strong>An audit trail table</strong> — recording who did what when</li><li><strong>A timer service</strong> — handling timeouts and scheduled transitions</li><li><strong>A notification dispatch</strong> — triggering side effects on state changes</li></ol><p>SMQL provides all five out of the box, with a single declaration.</p><h2 id="when-smql-is-not-the-right-fit" tabindex="-1">When SMQL Is Not the Right Fit <a class="header-anchor" href="#when-smql-is-not-the-right-fit" aria-label="Permalink to &quot;When SMQL Is Not the Right Fit&quot;">​</a></h2><ul><li><strong>Simple CRUD</strong> — if your entities don&#39;t have meaningful state transitions, use a regular database</li><li><strong>Continuous data</strong> — time-series data, metrics, logs belong in specialized stores</li><li><strong>Graph traversal</strong> — complex relationship queries are better served by graph databases</li><li><strong>Full-text search</strong> — use Elasticsearch or similar for search-heavy workloads</li></ul>',21)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
